INSERT INTO luoghi_napoli (id, nome, tipo, indirizzo, lat, lon, anno_inizio, anno_fine, note, foto_url, confidence, verificato, fonte_id) VALUES (1, 'Stadio Diego Armando Maradona (già San Paolo)', 'stadio', 'Piazzale Vincenzo Tecchio, Fuorigrotta, Napoli', 40.827967, 14.193008, 1959, NULL, 'Inaugurato il 6 dicembre 1959 con Napoli-Juventus 2-1. Teatro dei due scudetti dell''era Maradona (1987, 1990) e del terzo tricolore nel 2023. Intitolato a Diego Armando Maradona il 4 dicembre 2020.', '/assets/aistudio/maradona_stadium.png', 'alta', 1, 5);
INSERT INTO luoghi_napoli (id, nome, tipo, indirizzo, lat, lon, anno_inizio, anno_fine, note, foto_url, confidence, verificato, fonte_id) VALUES (2, 'Stadio Giorgio Ascarelli (già Stadio Vesuvio)', 'stadio', 'Via Amedeo duca d''Aosta / Rione Luzzatti, Poggioreale, Napoli', 40.8542, 14.2889, 1930, 1942, 'Primo stadio di proprietà del Napoli, ideato e finanziato interamente da Giorgio Ascarelli. Inaugurato il 23 febbraio 1930 e distrutto dai bombardamenti aerei nel 1942.', '/assets/aistudio/stadio_ascarelli.png', 'alta', 1, 5);
INSERT INTO luoghi_napoli (id, nome, tipo, indirizzo, lat, lon, anno_inizio, anno_fine, note, foto_url, confidence, verificato, fonte_id) VALUES (3, 'Stadio Arturo Collana (già della Liberazione)', 'stadio', 'Piazza Quattro Giornate, Vomero, Napoli', 40.8436, 14.2272, 1929, 1959, 'Storica casa del club vomerese prima e durante il secondo dopoguerra, teatro delle gesta di Sallustro, Jeppson e Amadei prima del passaggio definitivo a Fuorigrotta.', '/assets/aistudio/stadio_collana.png', 'alta', 1, 5);
INSERT INTO luoghi_napoli (id, nome, tipo, indirizzo, lat, lon, anno_inizio, anno_fine, note, foto_url, confidence, verificato, fonte_id) VALUES (4, 'Campo Militare dell''Arenaccia', 'stadio', 'Via Arenaccia / Piazza Carlo III, Napoli', 40.8601, 14.2675, 1926, 1929, 'Il terreno su cui il neonato Associazione Calcio Napoli disputò le sue primissime gare ufficiali nel campionato di Divisione Nazionale 1926-27.', '/assets/aistudio/campo_arenaccia.png', 'alta', 1, 5);
INSERT INTO luoghi_napoli (id, nome, tipo, indirizzo, lat, lon, anno_inizio, anno_fine, note, foto_url, confidence, verificato, fonte_id) VALUES (5, 'Centro Sportivo Paradiso', 'centro_sportivo', 'Via Vicinale Paradiso, Soccavo, Napoli', 40.8492, 14.1944, 1975, 2004, 'Il quartier generale degli allenamenti dell''era d''oro. Qui Diego Armando Maradona affinava punizioni e magie quotidiane con compagni e staff.', '/assets/aistudio/centro_paradiso.png', 'alta', 1, 5);
INSERT INTO luoghi_napoli (id, nome, tipo, indirizzo, lat, lon, anno_inizio, anno_fine, note, foto_url, confidence, verificato, fonte_id) VALUES (6, 'SSCN Konami Training Center', 'centro_sportivo', 'Via Domitiana Km 35.300, Castel Volturno (CE)', 40.9412, 13.9878, 2006, NULL, 'Moderno centro tecnico della prima squadra con tre campi in erba naturale, palestre avanzate, centro medico e sale riunioni dell''era De Laurentiis.', '/assets/aistudio/castel_volturno.png', 'alta', 1, 5);
INSERT INTO luoghi_napoli (id, nome, tipo, indirizzo, lat, lon, anno_inizio, anno_fine, note, foto_url, confidence, verificato, fonte_id) VALUES (7, 'Sede Storica Via del Maio di Porto', 'sede', 'Via del Maio di Porto 9, Napoli', 40.8419, 14.2561, 1926, 1935, 'La sede primigenia dell''Associazione Calcio Napoli, dove Giorgio Ascarelli firmò l''atto fondativo e lo statuto del club il 1 agosto 1926.', '/assets/aistudio/sede_maio_porto.png', 'alta', 1, 5);
INSERT INTO luoghi_napoli (id, nome, tipo, indirizzo, lat, lon, anno_inizio, anno_fine, note, foto_url, confidence, verificato, fonte_id) VALUES (8, 'Sede Storica Piazza Carità', 'sede', 'Piazza Carità 32, Napoli', 40.8439, 14.2497, 1950, 1970, 'Sede centrale del club durante la presidenza di Achille Lauro e la conquista della prima Coppa Italia nel 1962.', '/assets/aistudio/sede_piazza_carita.png', 'alta', 1, 5);
INSERT INTO luoghi_napoli (id, nome, tipo, indirizzo, lat, lon, anno_inizio, anno_fine, note, foto_url, confidence, verificato, fonte_id) VALUES (9, 'Sede Storica Via San Pasquale a Chiaia', 'sede', 'Via San Pasquale a Chiaia 23, Napoli', 40.8353, 14.2386, 1975, 1995, 'Il quartier generale dirigenziale degli scudetti di Maradona, dove vennero depositati i contratti storici e la Coppa UEFA 1989.', '/assets/aistudio/sede_chiaia.png', 'alta', 1, 5);
INSERT INTO luoghi_napoli (id, nome, tipo, indirizzo, lat, lon, anno_inizio, anno_fine, note, foto_url, confidence, verificato, fonte_id) VALUES (10, 'Sede SSC Napoli Centro Direzionale', 'sede', 'Centro Direzionale Isola B5, Napoli', 40.8573, 14.2818, 1995, 2004, 'Sede amministrativa negli anni di transizione tra la fine degli anni novanta e l''inizio del nuovo millennio.', '/assets/aistudio/sede_cdn.png', 'alta', 1, 5);
INSERT INTO luoghi_napoli (id, nome, tipo, indirizzo, lat, lon, anno_inizio, anno_fine, note, foto_url, confidence, verificato, fonte_id) VALUES (11, 'Ritiro Dimaro Folgarida', 'ritiro', 'Dimaro Folgarida, Val di Sole (TN)', 46.3275, 10.8722, 2011, NULL, 'Tradizionale sede alpina del ritiro precampionato in Trentino, meta di migliaia di tifosi azzurri all''inizio di ogni stagione sportiva.', '/assets/aistudio/ritiro_dimaro.png', 'alta', 1, 5);
INSERT INTO luoghi_napoli (id, nome, tipo, indirizzo, lat, lon, anno_inizio, anno_fine, note, foto_url, confidence, verificato, fonte_id) VALUES (12, 'Ritiro Castel di Sangro', 'ritiro', 'Stadio Teofilo Patini, Castel di Sangro (AQ)', 41.7825, 14.1083, 2020, NULL, 'Seconda tappa del ritiro estivo in Abruzzo, sede di prestigiosi test match internazionali e sedute tattiche a porte aperte.', '/assets/aistudio/ritiro_casteldisangro.png', 'alta', 1, 5);
INSERT INTO luoghi_napoli (id, nome, tipo, indirizzo, lat, lon, anno_inizio, anno_fine, note, foto_url, confidence, verificato, fonte_id) VALUES (13, 'Murales di Maradona ai Quartieri Spagnoli', 'monumento', 'Via Emanuele De Deo 60, Quartieri Spagnoli, Napoli', 40.8415, 14.2464, 1990, NULL, 'Celeberrimo santuario a cielo aperto dipinto da Mario Filardi nel 1990 per il secondo scudetto, meta di pellegrinaggio laico e mondiale.', '/assets/aistudio/murales_quartieri.png', 'alta', 1, 5);
INSERT INTO luoghi_napoli (id, nome, tipo, indirizzo, lat, lon, anno_inizio, anno_fine, note, foto_url, confidence, verificato, fonte_id) VALUES (14, 'Largo Maradona e Murales di Jorit a San Giovanni', 'monumento', 'Via Taverna del Ferro, San Giovanni a Teduccio, Napoli', 40.8351, 14.3075, 2017, NULL, 'Il monumentale ritratto ''Dios Umano'' dipinto dallo street artist Jorit sul palazzone di Taverna del Ferro.', '/assets/aistudio/jorit_maradona.png', 'alta', 1, 5);
